window.C3KO_REVIEWS = {"A1":{"what":["Everyday sentences using only A1 grammar. Read each one, explain every part yourself, then check the breakdown.","Kalimat sehari-hari yang hanya memakai tata bahasa A1. Baca setiap kalimat, jelaskan sendiri setiap bagiannya, lalu periksa uraiannya."],"sentences":[{"en":["My name is Anna, I'm a teacher and I live in Munich.","Nama saya Anna, saya guru dan tinggal di München."],"parts":[["Ich heiße Anna,",["heißen: stem in ß, ich form -e","heißen: akar berakhiran ß, bentuk ich -e"],"a1-present"],["ich bin Lehrerin",["sein + job, no article; -in = female","sein + pekerjaan, tanpa artikel; -in = perempuan"],"a1-sein"],["und wohne in München.",["regular verb; und doesn't change word order","kata kerja beraturan; und tidak mengubah susunan"],"a1-word-order"]]},{"en":["Tomorrow I have to get up at half past six.","Besok saya harus bangun pukul setengah tujuh."],"parts":[["Morgen",["time word in position 1","kata waktu di posisi 1"],"a1-word-order"],["muss ich",["modal verb in position 2, subject after it","kata kerja modal di posisi 2, subjek setelahnya"],"a1-modals"],["um halb sieben",["um + time; halb sieben = 6:30","um + jam; halb sieben = 6.30"],"a1-numbers-time"],["aufstehen.",["separable verb stays whole at the end","kata kerja terpisah tetap utuh di akhir"],"a1-separable"]]},{"en":["Do you have a car? — No, I don't have a car.","Kamu punya mobil? — Tidak, saya tidak punya mobil."],"parts":[["Hast du ein Auto?",["yes/no question: verb first; haben, du form","pertanyaan ya/tidak: kata kerja di depan; haben, bentuk du"],"a1-haben"],["— Nein, ich habe kein Auto.",["ein + noun → kein","ein + kata benda → kein"],"a1-negation"]]},{"en":["My brother is reading the newspaper and drinking a coffee.","Saudara laki-laki saya sedang membaca koran dan minum kopi."],"parts":[["Mein Bruder",["mein: masculine, nominative","mein: maskulin, nominatif"],"a1-possessives"],["liest",["lesen: e → ie for er","lesen: e → ie untuk er"],"a1-present-stem"],["die Zeitung",["-ung nouns are feminine","kata benda -ung feminin"],"a1-gender"],["und trinkt einen Kaffee.",["der Kaffee → einen (masculine accusative)","der Kaffee → einen (akusatif maskulin)"],"a1-accusative"]]},{"en":["Where do you (polite) come from? — From Indonesia.","Anda berasal dari mana? — Dari Indonesia."],"parts":[["Woher kommen Sie?",["woher = where from; Sie = polite you","woher = dari mana; Sie = Anda"],"a1-questions"],["— Aus Indonesien.",["aus = from (a country)","aus = dari (negara)"],null]]},{"en":["In summer the children play in the garden.","Di musim panas anak-anak bermain di kebun."],"parts":[["Im Sommer",["im + season","im + musim"],"a1-prep-time"],["spielen",["verb second; wir/sie form -en","kata kerja kedua; bentuk sie (mereka) -en"],"a1-word-order"],["die Kinder",["plural of das Kind: -er","jamak das Kind: -er"],"a1-plurals"],["im Garten.",["im = in dem (location)","im = in dem (lokasi)"],null]]}]},"A2":{"what":["Sentences that combine A2 grammar (plus A1). Read each one, explain every part yourself, then check the breakdown.","Kalimat yang menggabungkan tata bahasa A2 (dan A1). Baca setiap kalimat, jelaskan sendiri setiap bagiannya, lalu periksa uraiannya."],"sentences":[{"en":["Yesterday I went to the doctor because I was ill.","Kemarin saya ke dokter karena sakit."],"parts":[["Gestern bin ich",["time in position 1, verb 2; gehen takes sein","waktu di posisi 1, kata kerja 2; gehen memakai sein"],"a2-perfekt-sein"],["zum Arzt",["zu + dem = zum (dative)","zu + dem = zum (datif)"],"a2-prepositions"],["gegangen,",["Partizip II at the end","Partizip II di akhir"],"a2-perfekt-sein"],["weil ich krank war.",["weil sends the verb to the end; war = Präteritum of sein","weil mengirim kata kerja ke akhir; war = Präteritum sein"],"a2-subordinate"]]},{"en":["I gave my sister a new bike.","Saya memberi saudara perempuan saya sepeda baru."],"parts":[["Ich habe",["Perfekt with haben","Perfekt dengan haben"],"a2-perfekt-haben"],["meiner Schwester",["dative: the receiver (feminine → meiner)","datif: penerima (feminin → meiner)"],"a2-dative"],["ein neues Fahrrad",["neuter accusative after ein → -es","akusatif netral setelah ein → -es"],"a2-adj-indefinite"],["geschenkt.",["weak participle ge-…-t","partisip lemah ge-…-t"],"a2-perfekt-haben"]]},{"en":["I'm putting the book on the table; now it's lying on the table.","Saya menaruh buku di atas meja; sekarang buku itu ada di atas meja."],"parts":[["Ich lege das Buch auf den Tisch;",["legen + wohin → accusative","legen + wohin → akusatif"],"a2-wo-wohin"],["jetzt liegt es auf dem Tisch.",["liegen + wo → dative","liegen + wo → datif"],"a2-two-way"]]},{"en":["I like the red dress, but it's more expensive than the blue one.","Saya suka gaun merah itu, tetapi lebih mahal daripada yang biru."],"parts":[["Das rote Kleid",["after das → -e","setelah das → -e"],"a2-adj-definite"],["gefällt mir,",["gefallen + dative: the dress pleases me","gefallen + datif: gaun itu menyenangkan saya"],"a2-dative-verbs"],["aber es ist teurer als das blaue.",["aber: normal word order; teurer als: comparison","aber: susunan biasa; teurer als: perbandingan"],"a2-comparison"]]},{"en":["I'm looking forward to the holidays, that's why I'm working a lot now.","Saya menantikan liburan, karena itu sekarang saya banyak bekerja."],"parts":[["Ich freue mich auf den Urlaub,",["sich freuen auf + accusative: look forward to","sich freuen auf + akusatif: menantikan"],"a2-reflexive"],["deshalb arbeite ich",["deshalb takes position 1: verb follows","deshalb di posisi 1: kata kerja menyusul"],"a2-conjunctions"],["jetzt viel.",["time word in the middle","kata waktu di tengah"],null]]},{"en":["Please help me, I couldn't find my key.","Tolong bantu saya, saya tidak bisa menemukan kunci saya."],"parts":[["Hilf mir bitte,",["du imperative of helfen (e → i) + dative mir","imperatif du dari helfen (e → i) + datif mir"],"a2-imperative"],["ich konnte",["Präteritum of können","Präteritum können"],"a2-praeteritum-basic"],["meinen Schlüssel nicht finden.",["meinen: masculine accusative; infinitive at the end after a modal","meinen: akusatif maskulin; infinitif di akhir setelah modal"],null]]}]},"B1":{"what":["Sentences that combine B1 grammar with earlier levels. Read each one, explain every part yourself, then check the breakdown.","Kalimat yang menggabungkan tata bahasa B1 dengan level sebelumnya. Baca setiap kalimat, jelaskan sendiri setiap bagiannya, lalu periksa uraiannya."],"sentences":[{"en":["If I had more time, I would learn Japanese.","Kalau saya punya lebih banyak waktu, saya akan belajar bahasa Jepang."],"parts":[["Wenn ich mehr Zeit hätte,",["wenn + Konjunktiv II of haben: unreal condition; verb last","wenn + Konjunktiv II haben: syarat tidak nyata; kata kerja di akhir"],"b1-konjunktiv2"],["würde ich",["main clause starts with its verb: würde","induk kalimat dimulai dengan kata kerja: würde"],"b1-konjunktiv2"],["Japanisch lernen.",["infinitive at the end","infinitif di akhir"],null]]},{"en":["The man who helped me yesterday is a doctor.","Laki-laki yang membantu saya kemarin adalah dokter."],"parts":[["Der Mann,",["masculine noun: der Mann","kata benda maskulin: der Mann"],null],["der mir gestern geholfen hat,",["relative pronoun der (subject); helfen + dative mir; verb last","kata ganti relatif der (subjek); helfen + datif mir; kata kerja di akhir"],"b1-relative"],["ist Arzt.",["sein + job without article","sein + pekerjaan tanpa artikel"],null]]},{"en":["When I was a child, the old house was sold.","Ketika saya masih kecil, rumah tua itu dijual."],"parts":[["Als ich ein Kind war,",["als: one period in the past","als: satu periode di masa lalu"],"b1-als-wenn"],["wurde das alte Haus",["passive Präteritum: wurde + Partizip II","pasif Präteritum: wurde + Partizip II"],"b1-passive"],["verkauft.",["participle at the end","partisip di akhir"],"b1-passive"]]},{"en":["I'm learning German in order to study in Vienna, although it's hard.","Saya belajar bahasa Jerman supaya bisa kuliah di Wina, meskipun sulit."],"parts":[["Ich lerne Deutsch,",["main clause","induk kalimat"],null],["um in Wien zu studieren,",["um … zu: same subject, purpose","um … zu: subjek sama, tujuan"],"b1-um-zu-damit"],["obwohl es schwer ist.",["obwohl: verb at the end","obwohl: kata kerja di akhir"],"b1-obwohl-trotzdem"]]},{"en":["After we had eaten, we talked about the trip.","Setelah makan, kami membicarakan perjalanan itu."],"parts":[["Nachdem wir gegessen hatten,",["Plusquamperfekt after nachdem","Plusquamperfekt setelah nachdem"],"b1-plusquamperfekt"],["sprachen wir",["Präteritum of sprechen (strong: sprach)","Präteritum sprechen (kuat: sprach)"],"b1-praeteritum"],["über die Reise.",["sprechen über + accusative","sprechen über + akusatif"],"b1-prep-verbs"]]},{"en":["Can you tell me whether my colleague has already arrived?","Bisakah Anda memberi tahu saya apakah rekan saya sudah tiba?"],"parts":[["Können Sie mir sagen,",["polite question introducing an indirect question","pertanyaan sopan pembuka pertanyaan tidak langsung"],null],["ob mein Kollege",["ob for yes/no; der Kollege (n-declension, nominative here)","ob untuk ya/tidak; der Kollege (deklinasi -n, di sini nominatif)"],"b1-indirect-questions"],["schon angekommen ist?",["verb last in the indirect question","kata kerja di akhir pertanyaan tidak langsung"],"b1-indirect-questions"]]},{"en":["The more I read, the better I understand German texts.","Semakin banyak saya membaca, semakin baik saya memahami teks bahasa Jerman."],"parts":[["Je mehr ich lese,",["je + comparative; verb at the end","je + komparatif; kata kerja di akhir"],"b1-two-part-conj"],["desto besser verstehe ich",["desto + comparative + verb","desto + komparatif + kata kerja"],"b1-two-part-conj"],["deutsche Texte.",["no article, plural accusative → -e","tanpa artikel, akusatif jamak → -e"],"b1-adj-no-article"]]}]}};
